insert into public.emotion_families (emotion_family_id, family_code, family_name_vn, family_name_en, color_hex, active, sort_order)
values
('EFAM_001', 'Joy_Vitality', 'Hân hoan & Sinh lực', 'Joy & Vitality', '#F6C945', true, 1),
('EFAM_002', 'Calm_Ease', 'Bình yên & Thư thái', 'Calm & Ease', '#3FCF8E', true, 2),
('EFAM_003', 'Love_Connection', 'Yêu thương & Gắn kết', 'Love & Connection', '#FF6F91', true, 3),
('EFAM_004', 'Interest_Expansion', 'Hứng thú & Vươn mở', 'Interest & Expansion', '#2EC4B6', true, 4),
('EFAM_005', 'Uncertainty_Disorientation', 'Bất định & Lệch nhịp', 'Uncertainty & Disorientation', '#9B8AFB', true, 5),
('EFAM_006', 'Anxiety_Alarm', 'Lo âu & Báo động', 'Anxiety & Alarm', '#FF9F43', true, 6),
('EFAM_007', 'Anger_Rejection', 'Bực bội & Khước từ', 'Anger & Rejection', '#FF5A5F', true, 7),
('EFAM_008', 'Sadness_Loss', 'Buồn đau & Mất mát', 'Sadness, Loss & Longing', '#4D96FF', true, 8),
('EFAM_009', 'SelfConscious_Evaluation', 'Tự ý thức & Tự đánh giá', 'Self-Consciousness & Self-Evaluation', '#D06BC7', true, 9),
('EFAM_010', 'LowEnergy_Disconnection', 'Cạn năng lượng & Tách rời', 'Low Energy & Disconnection', '#718096', true, 10)
insert into public.emotions (emotion_id, emotion_family_id, emotion_name_vn, emotion_name_en, emoji, color_hex, description_vn, description_en, active, sort_order)
values
('EMO_001', 'EFAM_001', 'Vui vẻ', 'Cheerful', '😁', '#FFE066', 'Mình cảm thấy sáng sủa, dễ chịu và có thể tận hưởng điều đang diễn ra mà không cần một lý do quá lớn. Niềm vui này thường vừa phải, gần gũi và khiến mình muốn mỉm cười, chia sẻ hoặc ở lại lâu hơn với khoảnh khắc hiện tại.', 'I feel bright, pleasantly uplifted, and able to enjoy what is happening without needing a major reason. This is an everyday kind of joy that may make me smile, share the moment, or simply stay with it a little longer.', true, 1),
('EMO_002', 'EFAM_001', 'Vui vẻ hòa đồng', 'Jovial', '😄', '#F7C948', 'Mình đang vui theo một cách cởi mở, thân thiện và dễ lan sang những người xung quanh. Không chỉ bản thân thấy vui, mình còn muốn trò chuyện, pha trò, hòa vào không khí chung và giúp khoảnh khắc giữa mọi người trở nên nhẹ nhàng hơn.', 'I feel cheerful in an open, sociable, and good-humored way that can easily spread to those around me. My enjoyment is not entirely private; I feel inclined to talk, joke, join the shared atmosphere, and make the moment more pleasant for others.', true, 2),
('EMO_003', 'EFAM_001', 'Hân hoan', 'Elated', '🤩', '#FFD43B', 'Một niềm vui mạnh đang lan rộng trong mình vì điều gì đó thật sự tốt đẹp vừa xảy ra, được nhận ra hoặc trở thành sự thật. Mình có thể cảm thấy được nâng lên, muốn reo vui, ăn mừng hoặc chia sẻ niềm vui ấy với người khác.', 'An intense joy spreads through me because something deeply welcome has happened, been realized, or become true. I may feel lifted and moved to celebrate, exclaim, or share the joy with others.', true, 3),
('EMO_004', 'EFAM_001', 'Vỡ òa', 'Overcome with Joy / Emotionally Bursting', '🥹', '#FFB52E', 'Một cảm xúc tích cực đã tích tụ trong mình rồi bất ngờ bùng ra khi điều mình chờ đợi, hy vọng hoặc cố gắng cuối cùng cũng thành hiện thực. Mình có thể vừa cười vừa khóc hoặc cảm thấy không còn cần giữ cảm xúc lại nữa. Khác với hân hoan là niềm vui mạnh, vỡ òa nhấn vào khoảnh khắc cảm xúc được giải phóng sau một thời gian tích tụ.', 'Positive emotion that has been building inside me suddenly bursts out when something I hoped for, waited for, or worked toward finally becomes real. I may laugh, cry, or feel unable to hold the emotion in any longer. Unlike general elation, this emphasizes the release of accumulated emotion.', true, 4),
('EMO_005', 'EFAM_001', 'Phấn khích', 'Excited', '🎉', '#FF9F1C', 'Mình thấy năng lượng dâng lên và muốn tham gia ngay vào một điều đang hoặc sắp diễn ra. Điểm nổi bật là sự kích thích, rạo rực lúc này; còn háo hức nhấn vào niềm vui mong chờ điều chưa đến.', 'I feel energized and drawn to take part in something happening now or about to happen. The focus is my current surge of activation; eagerness puts more emphasis on pleasantly looking forward to an experience.', true, 5),
('EMO_006', 'EFAM_001', 'Háo hức', 'Eager / Looking forward', '🤗', '#FFC125', 'Mình thấy vui khi nghĩ đến một điều sắp tới và mong được trải nghiệm nó. Khác với phấn khích nhấn vào năng lượng dâng lên, háo hức nhấn vào sự mong đợi dễ chịu; khác với nôn nóng, sự chờ đợi chưa nhất thiết làm mình bực.', 'I feel pleasure in anticipating an upcoming experience and look forward to it. Unlike excitement''s surge of activation, eagerness emphasizes pleasant anticipation; unlike impatience, waiting need not feel irritating.', true, 6),
('EMO_007', 'EFAM_001', 'Phơi phới', 'Buoyant / High-Spirited', '🌤️', '#F5C451', 'Mình cảm thấy vui và đầy sinh lực theo cách nhẹ, thoáng, như có thêm đà để bước ra ngoài, làm việc hoặc tận hưởng những gì đang ở quanh mình. Khác với phấn khích có độ kích hoạt mạnh và thường hướng vào một điều cụ thể, phơi phới là trạng thái tươi sáng lan rộng và tương đối nhẹ nhàng.', 'I feel bright, buoyant, and full of light energy, as though I have extra momentum to engage with life and enjoy what is around me. Unlike excitement, which is more intensely activated and often focused on something specific, high spirits are broader, lighter, and more sustained.', true, 7),
('EMO_008', 'EFAM_001', 'Lâng lâng', 'Lightly Euphoric / Floating', '☁️', '#FFD86B', 'Mình cảm thấy vui, nhẹ và hơi như đang “bay”, thường sau một điều rất dễ chịu, đáng vui hoặc khiến cảm xúc được nâng lên. Khác với hân hoan mạnh và bùng nổ hơn, lâng lâng có chất nhẹ, mềm và kéo dài như một dư âm dễ chịu.', 'I feel pleasantly light and slightly as if I am floating, often after something joyful, rewarding, or emotionally uplifting. Unlike the stronger intensity of elation, this feeling is softer and may linger as a pleasant afterglow.', true, 8),
('EMO_009', 'EFAM_001', 'Thích thú', 'Delighted', '😺', '#F6BD60', 'Mình cảm thấy vui thích trước một điều cụ thể vừa thấy, nghe hoặc trải nghiệm và muốn tận hưởng nó thêm. Khác với hứng thú chủ yếu giữ sự chú ý, thích thú nhấn vào niềm vui mà chính điều ấy mang lại.', 'I feel pleased by something specific that I have seen, heard, or experienced and want to enjoy it a little longer. Unlike interest, which centers on sustained attention, delight emphasizes the pleasure the experience brings.', true, 9),
('EMO_010', 'EFAM_001', 'Thấy buồn cười', 'Amused', '😂', '#FFB703', 'Một điều gì đó vừa chạm đúng phần hài hước trong mình, khiến mình muốn mỉm cười hoặc bật cười. Cảm giác này thường đến từ sự bất ngờ, lệch nhịp hoặc ngộ nghĩnh theo một cách vô hại và dễ chịu.', 'Something has struck me as funny, playful, or harmlessly unexpected, bringing an impulse to smile or laugh. Amusement is usually a receptive response to humor rather than an urge to create the play myself.', true, 10),
('EMO_011', 'EFAM_001', 'Tinh nghịch', 'Playful', '😜', '#FB8500', 'Mình thấy vui, nghịch ngợm và muốn đùa, trêu nhẹ hoặc thử cách làm ngẫu hứng. Niềm vui nằm ở việc chơi và tương tác lúc này, chứ không phải mong muốn được có thêm thời gian vui chơi.', 'I feel playful and inclined to joke, gently tease, or try something spontaneous. The enjoyment is in playing and interacting right now, rather than in wishing I had more time for play.', true, 11),
('EMO_012', 'EFAM_001', 'Đắc ý', 'Pleased with myself / Self-satisfied', '😎', '#EBAE24', 'Mình thấy khoái chí với bản thân vì vừa làm đúng, đoán đúng hoặc có được kết quả như ý. Khác với tự tin hướng vào khả năng ứng phó, đắc ý là sự hài lòng với điều vừa xảy ra; không nhất thiết có ý xem thường người khác.', 'I feel pleased with myself for being right, doing something well, or getting a satisfying result. Unlike confidence in my ability to cope, this is satisfaction with what just happened and need not involve looking down on others.', true, 12),
('EMO_013', 'EFAM_001', 'Hả hê trước điều không may của người khác', 'Schadenfreude', '😏', '#C98B38', 'Mình nhận ra mình có chút vui hoặc hả hê trước một điều không may của người khác. Khác với đắc ý vì bản thân làm được điều gì, niềm vui ở đây gắn với bất lợi của người kia; nhận ra cảm giác không có nghĩa mình tán thành việc gây hại.', 'I notice pleasure or satisfaction at another person''s misfortune. Unlike being pleased with my own success, the pleasure centers on their disadvantage; noticing the feeling does not mean endorsing harm.', true, 13),
('EMO_014', 'EFAM_002', 'Bình yên', 'Peaceful', '🕊️', '#52B788', 'Bên trong mình đang tương đối yên, không có điều gì kéo, thúc hoặc đe dọa quá mạnh. Mình vẫn tỉnh táo và có mặt, nhưng không cần liên tục phòng thủ, phản ứng hay giải quyết điều gì ngay lúc này.', 'I feel an inner quiet in which nothing is strongly pulling, pressuring, or threatening me. I remain aware and present without needing to defend myself, react, or solve something immediately.', true, 14),
('EMO_015', 'EFAM_002', 'Thư thái / Thảnh thơi', 'Relaxed / At ease', '🛋️', '#67C79A', 'Cơ thể và đầu óc đã bớt giữ lực, đồng thời mình cũng tạm rời khỏi cảm giác phải làm, phải gồng hoặc phải theo kịp. Hơi thở, chuyển động và sự chú ý trở nên tự nhiên hơn, như thể mình được phép nghỉ trong chính khoảnh khắc này.', 'My body and mind are releasing tension, and I feel temporarily free from the pressure to perform, keep up, or hold everything together. Breathing, movement, and attention become easier, as though I am allowed to rest within the moment.', true, 15),
('EMO_016', 'EFAM_002', 'An tâm', 'Reassured', '🛡️', '#55A630', 'Điều từng khiến mình lo hoặc chưa chắc chắn đã có thêm thông tin, sự xác nhận hoặc điểm tựa để dịu xuống. Mình chưa cần biết mọi thứ sẽ hoàn hảo, nhưng đã có đủ cơ sở để bớt cảnh giác và tin rằng mình có thể ổn.', 'Something that had worried or unsettled me now feels more manageable because I have gained information, reassurance, or support. I do not need certainty that everything will be perfect; I have enough to lower my guard and trust that I can be okay.', true, 16),
('EMO_017', 'EFAM_002', 'Vững vàng', 'Grounded', '🪵', '#40916C', 'Mình cảm thấy có nền, có điểm tựa và không dễ bị hoàn cảnh kéo đi khỏi chính mình. Dù mọi thứ chưa hẳn yên, mình vẫn cảm nhận được mình đang đứng ở đâu, điều gì quan trọng và mình có thể giữ nhịp thế nào.', 'I feel anchored, supported, and less likely to be swept away by circumstances. Even if the situation is not fully calm, I can sense where I stand, what matters, and how to keep my footing.', true, 17),
('EMO_018', 'EFAM_002', 'Hài lòng', 'Content', '😊', '#A7C957', 'Mình cảm thấy điều đang có là đủ hoặc đang nằm ở một chỗ khá phù hợp với mình. Không nhất thiết có niềm vui lớn; chỉ là mình không bị thôi thúc phải có thêm, sửa ngay hoặc làm cho khoảnh khắc này trở thành một điều khác.', 'What is present feels sufficient or fitting for me right now. I do not need intense joy; I simply do not feel an urgent need for more, for immediate change, or for the moment to become something else.', true, 18),
('EMO_019', 'EFAM_002', 'Nhẹ nhõm', 'Relieved', '😮‍💨', '#78CCA1', 'Một mối lo, áp lực hoặc nguy cơ vừa giảm xuống, đi qua hoặc hóa ra không nghiêm trọng như mình sợ. Cảm giác rõ nhất là trước đó mình đã phải căng lên, còn bây giờ thì có thể thở ra và buông bớt.', 'A worry, pressure, or threat has eased, passed, or proved less serious than I feared. The contrast is clear: I had been bracing myself, and now I can exhale and let some of that tension go.', true, 19),
('EMO_020', 'EFAM_002', 'Sảng khoái', 'Refreshed', '🌊', '#63C7B2', 'Mình cảm thấy như vừa được làm mới sau khi một phần mệt mỏi, bí bách hoặc nặng nề đã được rũ bớt. Đầu óc tỉnh hơn, tinh thần sáng hơn và cơ thể có thêm sinh khí để trở lại với điều đang diễn ra.', 'I feel renewed after some tiredness, heaviness, or stagnation has cleared away. My mind feels fresher, my mood brighter, and my body more alive and ready to re-engage with what is happening.', true, 20),
('EMO_021', 'EFAM_002', 'Trung tính hiện diện', 'Neutral presence', '😐', '#A0AEC0', 'Mình nhận biết rõ mình đang ở đây nhưng chưa thấy vui, buồn hay khó chịu nổi bật. Đây là trạng thái trung tính, không phải mặc nhiên bình yên, hờ hững hay tê lì, và cũng không có nghĩa mình không có cảm xúc.', 'I am aware of being present but do not notice a clearly pleasant or unpleasant feeling. This neutral state is not automatically peace, indifference, or numbness, and does not mean that I have no emotions.', true, 21),
('EMO_022', 'EFAM_003', 'Yêu thương', 'Loving', '❤️', '#FF4D6D', 'Một tình cảm ấm áp đang hướng từ mình về một người, một sự sống hoặc một phần của chính mình. Mình muốn đến gần, quan tâm, gìn giữ và mong điều tốt cho đối tượng ấy, không chỉ vì họ hữu ích hay đáp ứng điều gì cho mình.', 'A warm affection is moving from me toward another person, a living being, or a part of myself. I want to come closer, care, protect, and wish them well beyond what they can do for me.', true, 22),
('EMO_023', 'EFAM_003', 'Trìu mến', 'Tender', '🌷', '#F38DB0', 'Lòng mình mềm lại trước một người, một sự sống hoặc điều đáng quý, khiến mình muốn nâng niu và đến gần thật nhẹ. Khác với ấm lòng là cảm giác ấm lên trong mình, trìu mến có hướng tình cảm rõ hơn về đối tượng ấy.', 'My heart softens toward someone, a living being, or something precious, and I feel drawn to cherish it gently. Unlike heartwarming feelings within me, tenderness is more clearly directed toward the person or thing I cherish.', true, 23),
('EMO_024', 'EFAM_003', 'Cưng quá muốn ôm siết', 'Overwhelmed by cuteness / Gigil', '😻', '#FFB347', 'Mình thấy một người hay điều gì quá đáng yêu, đến mức tình cảm dâng lên và muốn ôm siết hoặc véo nhẹ. Điểm chính là sự trìu mến mạnh trước nét đáng yêu, không phải tức giận hay muốn làm đau; cách gọi ở đây chỉ chọn sắc thái này của gigil.', 'I find someone or something so adorable that affection wells up with an impulse to squeeze or gently pinch. The focus is affection stirred by cuteness, not anger or a wish to hurt; this label uses that particular sense of gigil.', true, 24),
('EMO_025', 'EFAM_003', 'Được thương', 'Feeling loved', '🥰', '#FF8FAB', 'Mình cảm thấy ấm áp và mềm lòng khi cảm nhận tình thương đang hướng về mình. Đây là trải nghiệm đang được thương, không phải mong muốn được quan tâm; nó cũng không khẳng định chắc chắn ý định của người khác.', 'I feel warm and emotionally held as I experience affection directed toward me. This describes feeling loved now, not wishing for care, and does not establish another person''s intentions as a fact.', true, 25),
('EMO_026', 'EFAM_003', 'Thân thuộc / Gần gũi', 'Familiar and close', '🤗', '#FF99AC', 'Ở bên người này, nơi này hoặc trong mối quan hệ này, mình cảm thấy quen, dễ trở về và khoảng cách giữa hai bên được thu ngắn. Mình không phải mất quá nhiều sức để dò xét hay diễn giải, nên có thể hiện diện tự nhiên và chia sẻ thật hơn.', 'With this person, place, or relationship, I feel a sense of familiarity and reduced emotional distance. I do not have to spend as much energy scanning or translating myself, so I can be more natural and genuinely connected.', true, 26),
('EMO_027', 'EFAM_003', 'Cảm thấy thuộc về', 'Belonging', '🫂', '#E76F91', 'Mình thấy gần gũi và có chỗ trong một mối quan hệ hay nhóm, như thể mình là một phần của «chúng ta». Đây là cảm giác thuộc về đang có; khác với nhu cầu được bao hàm khi mình chưa cảm thấy điều đó.', 'I feel connected and at home in a relationship or group, as though I am part of a meaningful ''we''. This describes a present sense of belonging, rather than a wish to be included when that feeling is absent.', true, 27),
('EMO_028', 'EFAM_003', 'Cảm thấy được thấu hiểu', 'Feeling understood', '👀', '#D98593', 'Mình thấy nhẹ lòng và gần người kia hơn vì có cảm giác họ nắm được điều mình đang trải qua. Trọng tâm là trải nghiệm được hiểu trong khoảnh khắc này, không phải yêu cầu họ phải hiểu mình hay khẳng định họ đã hiểu hoàn toàn.', 'I feel relieved and closer to someone because it seems that they grasp what I am experiencing. The focus is feeling understood in this moment, not a demand to be understood or a claim that their understanding is complete.', true, 28),
('EMO_029', 'EFAM_003', 'Tin tưởng', 'Trusting', '🤝', '#F28FA5', 'Mình cảm thấy có thể đặt niềm tin vào một người, một mối quan hệ hoặc điều mình đang dựa vào mà không cần liên tục đề phòng hay kiểm chứng. Đây là trải nghiệm đang có của sự tin cậy, khác với nhu cầu được an toàn hoặc được bảo đảm.', 'I feel able to trust a person, relationship, or something I am relying on without constantly guarding myself or checking for danger. This describes a present experience of trust rather than a need for safety or reassurance.', true, 29),
('EMO_030', 'EFAM_003', 'Đồng điệu', 'In Tune / Emotionally Resonant', '🫂', '#E978A6', 'Mình cảm thấy cảm xúc, suy nghĩ hoặc nhịp trải nghiệm của mình hòa khớp với một người hay điều gì đó, như thể có một sự cộng hưởng tự nhiên. Khác với cảm thấy được thấu hiểu, đồng điệu không nhất thiết đòi hỏi người kia hiểu hay giải thích mình; trọng tâm là cảm giác “cùng tần số”.', 'I feel that my emotions, thoughts, or inner rhythm resonate naturally with another person or experience, as if we are on the same wavelength. Unlike feeling understood, resonance does not require the other person to explicitly understand or explain me; the focus is the felt sense of attunement.', true, 30),
('EMO_031', 'EFAM_003', 'Biết ơn', 'Grateful', '🙏', '#F4978E', 'Mình thấy trân trọng một điều tốt đã nhận được hoặc đang có trong đời, thay vì xem nó là hiển nhiên. Khác với cảm động là cảm giác bị chạm sâu, biết ơn hướng rõ hơn vào sự ghi nhận điều tốt và người hay hoàn cảnh đã góp phần mang nó đến.', 'I feel appreciative of something good I have received or have in my life, rather than taking it for granted. Unlike being moved, gratitude focuses more specifically on appreciating the good and whoever or whatever helped make it possible.', true, 31),
('EMO_032', 'EFAM_003', 'Ấm lòng', 'Heartwarmed', '🫶', '#F18A79', 'Mình thấy lòng ấm và dịu lại trước một sự tử tế, gần gũi hay khoảnh khắc đẹp giữa người với người. Không nhất thiết điều ấy hướng trực tiếp về mình; khác với cảm động có thể khiến mình nghẹn lại vì bị chạm sâu, ấm lòng nhấn vào sự ấm áp đang lan lên.', 'I feel warmth and softness in response to kindness, closeness, or a meaningful human moment. It need not be directed at me; unlike being deeply moved, the emphasis is on an inner glow of warmth.', true, 32),
('EMO_033', 'EFAM_003', 'Cảm động', 'Moved / Touched', '🥹', '#EF7194', 'Mình thấy một lời nói, sự tử tế, ký ức hay khoảnh khắc vừa chạm sâu vào tình cảm, có thể khiến mình nghẹn hoặc rưng rưng. Khác với biết ơn là ghi nhận điều tốt đã nhận, cảm động không cần có ai giúp mình và có thể pha cả vui lẫn buồn.', 'I feel deeply touched by words, kindness, a memory, or a meaningful moment, perhaps with tears or a lump in my throat. Unlike gratitude for a benefit, being moved does not require receiving help and may mix joy with sadness.', true, 33),
('EMO_034', 'EFAM_003', 'Mủi lòng', 'Tenderly Softened', '🥺', '#F58AA6', 'Lòng mình mềm xuống trước một người, lời nói, ký ức hoặc hoàn cảnh, khiến sự cứng rắn hay phòng thủ giảm đi và mình dễ thương cảm hoặc dịu lại hơn. Khác với cảm động là bị chạm sâu đến mức có thể nghẹn hoặc rưng rưng, mủi lòng nhấn vào sự mềm lại trong cách mình cảm và phản ứng.', 'I feel my heart soften toward a person, words, memory, or situation, reducing some of my firmness or defensiveness and making tenderness or sympathy easier. Unlike being deeply moved, which may bring tears or a lump in the throat, this feeling centers on the softening itself.', true, 34),
('EMO_035', 'EFAM_003', 'Trắc ẩn', 'Compassionate', '💞', '#FF7FA3', 'Mình cảm thấy thương trước nỗi khó của người khác và có thôi thúc muốn giảm bớt nỗi khó ấy. Khác với xót xa nhấn vào nỗi đau se lòng khi chứng kiến, trắc ẩn có thêm hướng muốn đáp lại bằng sự chăm sóc, dù mình chưa hành động.', 'I feel concern for someone who is suffering and an impulse to ease their difficulty. Compared with a sorrowful ache at witnessing suffering, compassion also includes a caring orientation, even before I take any action.', true, 35),
('EMO_036', 'EFAM_003', 'Thương mình', 'Self-compassion', '🤲', '#F47FA4', 'Mình cảm thấy dịu lại với phần đau, sai sót hoặc chưa hoàn hảo của chính mình, thay vì chỉ muốn trách phạt. Trải nghiệm này hướng sự tử tế vào bản thân ngay lúc này; không đồng nghĩa với việc phủ nhận trách nhiệm.', 'I feel gentler toward my own pain, mistakes, or imperfections instead of only wanting to punish myself. This experience directs kindness toward myself in the present without requiring me to deny responsibility.', true, 36),
('EMO_037', 'EFAM_003', 'Lưu luyến', 'Lingering attachment / Reluctant to part', '👋', '#E779A0', 'Mình thấy còn gắn bó và chưa nỡ rời một người, nơi, khoảnh khắc hoặc giai đoạn đang sắp kết thúc. Khác với nhớ nhung khi điều ấy đã vắng mặt, lưu luyến nổi lên quanh lúc chia tay và có thể vừa ấm áp vừa se lòng.', 'I feel attached and reluctant to leave a person, place, moment, or period that is ending. Unlike longing once something is absent, this feeling gathers around parting and can be both warm and aching.', true, 37),
('EMO_038', 'EFAM_003', 'Luyến lưu sau bữa ăn', 'Lingering after-meal warmth', '☕', '#F08FA3', 'Mình thấy ấm áp và thích nán lại trò chuyện sau bữa ăn, như cuộc gặp vẫn còn điều muốn tận hưởng dù đã ăn xong. Đây là cảm giác gần gũi gắn với bối cảnh sau bữa ăn; sobremesa là tên bối cảnh ấy, không phải bản thân một cảm xúc.', 'I feel warmth and enjoyment in lingering over conversation after a meal, as though the encounter still has something to savor. This is a feeling in an after-meal setting; sobremesa names that setting, not an emotion itself.', true, 38),
('EMO_039', 'EFAM_004', 'Cởi mở', 'Open / Receptive', '🌱', '#34BAAC', 'Mình cảm thấy sẵn lòng đón nhận một góc nhìn, người hay trải nghiệm mới, thay vì lập tức khép lại hoặc phòng thủ. Khác với tò mò là muốn biết thêm, cởi mở là thái độ tiếp nhận đang có; mình có thể cởi mở mà chưa đồng ý hay muốn hành động.', 'I feel willing to receive a new perspective, person, or experience instead of immediately closing off or becoming defensive. Unlike curiosity as a wish to know more, receptiveness is openness to receiving; I need not agree or be ready to act.', true, 39),
('EMO_040', 'EFAM_004', 'Cảm thấy được là mình', 'Feeling authentic', '🪞', '#02C39A', 'Mình cảm thấy tự nhiên và ít phải diễn khi lời nói, lựa chọn hay cách thể hiện gần với điều mình thật sự cảm thấy. Đây là trải nghiệm được là mình đang có; khác với mong muốn có tự chủ hoặc được người khác cho phép sống chân thật.', 'I feel natural and less performative when my expression and choices fit what I genuinely feel. This is a present sense of authenticity, not a wish for autonomy or for permission from others to be myself.', true, 40),
('EMO_041', 'EFAM_004', 'Phóng khoáng', 'Free-spirited', '🕊️', '#2EC4B6', 'Mình cảm thấy thoáng hơn, bớt tự bó mình vào khuôn phép hoặc nhu cầu kiểm soát từng điều nhỏ. Khác với cởi mở là sẵn lòng đón nhận điều mới, phóng khoáng nhấn vào cảm giác ít bị ràng buộc trong cách sống và thể hiện lúc này.', 'I feel less constrained by conventions or by controlling every small detail. Unlike receptiveness to new input, this emphasizes feeling freer in how I live and express myself right now.', true, 41),
('EMO_042', 'EFAM_004', 'Tò mò', 'Curious', '🧐', '#35B9E9', 'Mình nhận ra có một điều chưa biết, chưa hiểu hoặc chưa khám phá hết, và khoảng trống ấy khiến mình muốn tiến lại gần. Tò mò thường mang theo một câu hỏi, dù mình chưa diễn đạt được thành lời hay chưa biết câu trả lời sẽ dẫn mình tới đâu.', 'I notice a gap in what I know or understand, and that gap draws me closer. Curiosity usually carries a question, even when I cannot yet put it into words or know where the answer may lead.', true, 42),
('EMO_043', 'EFAM_004', 'Hứng thú', 'Interested', '✨', '#00B4D8', 'Một chủ đề, người hoặc hoạt động đang thu hút sự chú ý và khiến mình muốn tìm hiểu hay tham gia thêm. Khác với say mê là bị cuốn sâu và khó rời sự chú ý, hứng thú có thể chỉ là một sức hút vừa đủ để mình muốn tiếp tục.', 'A subject, person, or activity attracts my attention and makes me want to learn or engage further. Unlike fascination, which can absorb me deeply, interest may be a more modest pull that makes continuing appealing.', true, 43),
('EMO_044', 'EFAM_004', 'Say mê', 'Fascinated / Absorbed', '🔭', '#139CB7', 'Mình bị cuốn sâu vào một người, chủ đề hoặc trải nghiệm, muốn ở lại với nó và thấy khó rời sự chú ý. Khác với hứng thú vừa đủ để muốn tìm hiểu thêm, say mê có sức hút mạnh; ở đây không đồng nghĩa với tập trung do bị ép hay một hành vi mất kiểm soát.', 'I feel deeply drawn into a person, subject, or experience and reluctant to turn my attention away. Unlike ordinary interest, fascination has a strong absorbing pull; it does not mean forced concentration or loss of behavioral control.', true, 44),
('EMO_045', 'EFAM_004', 'Có cảm hứng', 'Inspired', '💡', '#48CAE4', 'Một điều mình gặp khiến mình thấy được mở ra và muốn tạo ra, làm khác đi hoặc thử một khả năng mới. Khác với ngưỡng mộ tập trung vào điều đáng quý ở đối tượng, cảm hứng nhấn vào điều được đánh thức trong chính mình.', 'Something I encounter leaves me feeling lifted and drawn to create, change, or try a new possibility. Unlike admiration, which focuses on a valued quality in its object, inspiration emphasizes what the encounter awakens in me.', true, 45),
('EMO_046', 'EFAM_004', 'Ngưỡng mộ', 'Admiring', '⭐', '#24AAA6', 'Mình thấy trân trọng và bị thu hút bởi một phẩm chất, năng lực hoặc việc ai đó đã làm. Khác với đố kỵ có nỗi đau so sánh, ngưỡng mộ tập trung vào điều đáng quý ở họ; mình không nhất thiết muốn trở nên giống họ hay làm điều gì ngay.', 'I feel appreciation and attraction toward someone''s quality, ability, or action. Unlike envy''s painful comparison, admiration centers on what I value in them; I need not want to become like them or take action immediately.', true, 46),
('EMO_047', 'EFAM_004', 'Choáng ngợp trước điều lớn lao', 'Awe', '🌌', '#925BC0', 'Mình đang đứng trước một điều rộng lớn, đẹp đẽ, mạnh mẽ hoặc vượt ngoài khung hiểu biết quen thuộc, khiến mình vừa mở ra vừa cảm thấy mình nhỏ lại. Trải nghiệm này có thể làm cách mình nhìn thế giới rộng hơn, thay vì chỉ khiến mình không xử lý nổi.', 'I am encountering something vast, beautiful, powerful, or beyond my usual frame of understanding, making me feel both expanded and smaller. Awe can enlarge my perspective rather than simply exceed my capacity to cope.', true, 47),
('EMO_048', 'EFAM_004', 'Chợt thấy mỗi người một câu chuyện', 'Sonder', '🏙️', '#8C7AE6', 'Mình chợt xúc động hoặc thấy mình nhỏ lại khi nghĩ rằng người lạ trước mắt cũng có một đời sống riêng nhiều lớp như mình. Đây là một khoảnh khắc nhận ra đi kèm cảm xúc, không có nghĩa mình biết họ thật sự đang sống hay cảm thấy thế nào.', 'I feel moved or humbled by suddenly considering that a stranger has a complex inner life of their own. This is an emotionally meaningful realization, not knowledge of what that person actually experiences.', true, 48),
('EMO_049', 'EFAM_004', 'Chuyển biến trong cách nhìn', 'Shift in perspective / Metanoia', '🦋', '#5FAF9F', 'Mình cảm thấy một cách nhìn cũ về bản thân hay cuộc sống đang không còn vừa nữa, và cách nhìn khác đang dần mở ra. Đây là trải nghiệm chuyển biến có thể đi cùng nhiều cảm xúc; không phải một cảm xúc đơn lẻ hay bảo đảm mình đã thay đổi lâu dài.', 'I feel that an old way of seeing myself or life no longer quite fits and another perspective is emerging. This is a transitional experience that may hold several emotions, not a single emotion or proof of lasting change.', true, 49),
('EMO_050', 'EFAM_004', 'Sáng tỏ / Rõ ràng', 'Clear / Clarity', '🔦', '#0077B6', 'Mình cảm thấy một vấn đề, lựa chọn hoặc điều bên trong đã dễ nhìn và dễ hiểu hơn. Đây là cảm giác sáng rõ về cách hiểu của mình, không có nghĩa mọi điều mình nghĩ đều đúng hay mọi vấn đề đã được giải quyết.', 'I feel that a problem, choice, or inner experience has become easier to understand. This describes a subjective sense of clarity, not proof that my interpretation is correct or that everything is resolved.', true, 50),
('EMO_051', 'EFAM_004', 'Hy vọng', 'Hopeful', '🌤️', '#4CC6D9', 'Mình đang hướng về một kết quả mình mong muốn và vẫn cảm thấy nó có thể xảy ra, dù hiện tại chưa chắc chắn hoặc còn nhiều khó khăn. Hy vọng không phủ nhận thực tế; nó giữ cho tương lai chưa hoàn toàn đóng lại.', 'I am oriented toward a desired outcome and still sense that it may be possible, even though uncertainty or difficulty remains. Hope does not deny reality; it keeps the future from feeling completely closed.', true, 51),
('EMO_052', 'EFAM_004', 'Có động lực', 'Motivated', '🚀', '#0096C7', 'Mình cảm thấy có lực kéo để bắt đầu hoặc tiếp tục một việc vì điều ấy có ý nghĩa, hấp dẫn hoặc đáng làm với mình. Đây là trạng thái muốn hành động; khác với hứng thú chỉ giữ sự chú ý và quyết tâm nhấn vào cam kết theo đuổi.', 'I feel a pull to begin or continue something because it matters to me or feels appealing or worthwhile. This is a motivational state, distinct from attention-focused interest and the sustained commitment of determination.', true, 52),
('EMO_053', 'EFAM_004', 'Sẵn sàng', 'Ready', '🚪', '#0EAD69', 'Mình cảm thấy đã có thể bước vào việc tiếp theo, dù vẫn còn một chút lo hoặc chưa hoàn toàn chắc chắn. Khác với có động lực là muốn làm, sẵn sàng nhấn vào cảm giác mình có thể bắt đầu ngay lúc này.', 'I feel able to step into what comes next even if some worry or uncertainty remains. Unlike motivation, which emphasizes wanting to act, readiness emphasizes feeling prepared enough to begin now.', true, 53),
('EMO_054', 'EFAM_004', 'Tự tin', 'Confident', '🌟', '#2A9D8F', 'Mình cảm thấy tin vào khả năng ứng phó, học hoặc tìm cách xử lý điều trước mắt. Khác với đắc ý là vui với điều mình vừa làm đúng, tự tin hướng vào khả năng của mình; nó không đòi hỏi phải chắc chắn sẽ thành công.', 'I feel trust in my ability to cope, learn, or find a way through what is ahead. Unlike feeling pleased with something I have just done, confidence concerns my capability without requiring certainty of success.', true, 54),
('EMO_055', 'EFAM_004', 'Can đảm', 'Courageous', '🦁', '#00B894', 'Mình cảm thấy có thể tiến về điều quan trọng dù vẫn nhận ra nỗi sợ hay rủi ro. Đây là cảm giác dũng khí trong tình huống hiện tại, không phải đánh giá mình có đức tính can đảm nói chung hay bắt buộc phải tiếp tục bất chấp giới hạn.', 'I feel able to move toward something important while fear or risk is still present. This is a current sense of courage, not a judgment about my character or an obligation to continue regardless of my limits.', true, 55),
('EMO_056', 'EFAM_004', 'Quyết tâm', 'Determined', '🏹', '#06A77D', 'Mình cảm thấy kiên tâm với một hướng đã chọn và muốn tiếp tục theo đuổi dù có trở ngại. Khác với có động lực là lực kéo để làm, quyết tâm nhấn vào sự bền lòng và cam kết đang cảm nhận trong tình huống này.', 'I feel firmly committed to a direction I have chosen and inclined to persist through obstacles. Unlike motivation as a pull to act, determination emphasizes my current resolve and commitment.', true, 56),
('EMO_057', 'EFAM_005', 'Mơ hồ', 'Unclear', '🌁', '#8A7CCF', 'Mình chưa nhận ra rõ mình đang cảm thấy gì hoặc tình huống có ý nghĩa ra sao; mọi thứ còn thiếu nét. Khác với bối rối do những tín hiệu không khớp nhau, mơ hồ có thể đơn giản là trải nghiệm chưa đủ rõ để gọi tên.', 'My feeling or understanding of a situation has not yet taken a clear shape. Unlike confusion caused by conflicting signals, this may simply be an experience that is too indistinct to name.', true, 57),
('EMO_058', 'EFAM_005', 'Khó gọi tên cảm xúc', 'Difficulty identifying feelings', '🫧', '#8795A1', 'Mình nhận thấy bên trong có điều gì đó nhưng chưa phân biệt được đó là cảm xúc nào hoặc chưa tìm được lời để nói. Khác với tê lì là tín hiệu cảm xúc mờ đi, ở đây khó khăn nằm ở nhận diện và diễn đạt; một lần như vậy không đồng nghĩa với alexithymia.', 'I notice something happening inside but cannot yet identify the feeling or find words for it. Unlike numbness as muted emotional signals, the difficulty is naming and describing; one such experience does not establish alexithymia.', true, 58),
('EMO_059', 'EFAM_005', 'Bối rối', 'Confused', '😵‍💫', '#A66CFF', 'Mình thấy rối vì thông tin, tín hiệu hoặc cách hiểu đang không khớp nhau, nên chưa biết nên hiểu hay phản ứng thế nào. Khác với hoang mang, trọng tâm ở đây là sự rối trong cách hiểu, chưa nhất thiết có nỗi lo hay cảm giác mất điểm tựa.', 'I feel confused because information, signals, or interpretations do not fit together, leaving me unsure how to understand or respond. Unlike anxious bewilderment, the central difficulty is making sense of things rather than feeling distressed or unanchored.', true, 59),
('EMO_060', 'EFAM_005', 'Ngơ ngác', 'Bewildered / Momentarily Lost', '😯', '#B87AE6', 'Mình chưa bắt kịp điều vừa xảy ra nên tạm thời không biết chuyện gì đang diễn ra hoặc nên định hướng thế nào. Khác với hoang mang có thêm bất an rõ rệt, ngơ ngác thiên về trạng thái chưa kịp hiểu hoặc định vị mình sau một thay đổi hay thông tin bất ngờ.', 'I have not yet caught up with what just happened and momentarily do not know what is going on or how to orient myself. Unlike feeling distraught or confused with stronger anxiety, bewilderment here is mainly the temporary inability to make sense of or locate myself after something unexpected.', true, 60),
('EMO_061', 'EFAM_005', 'Lúng túng', 'Flustered / At a Loss', '🫣', '#9479E2', 'Mình tạm thời không biết nên nói gì, làm gì hoặc phản ứng thế nào cho tự nhiên trong tình huống hiện tại. Khác với bối rối chủ yếu là chưa hiểu chuyện gì đang xảy ra, lúng túng nhấn vào việc mình không biết nên xử trí ra sao.', 'I temporarily do not know what to say, do, or how to respond naturally in the situation. Unlike confusion, which mainly involves not understanding what is happening, being flustered centers on not knowing how to handle or respond to it.', true, 61),
('EMO_062', 'EFAM_005', 'Khó xử', 'Awkward / Torn', '😬', '#A286E8', 'Mình cảm thấy bị đặt vào một tình huống mà nói, làm hoặc chọn theo hướng nào cũng có điểm khiến mình không thoải mái. Khác với phân vân chủ yếu là chưa chọn được giữa các phương án, khó xử thường có thêm yếu tố quan hệ, hoàn cảnh hoặc hậu quả khiến lựa chọn nào cũng không hoàn toàn dễ dàng.', 'I feel caught in a situation where speaking, acting, or choosing in any direction carries some discomfort. Unlike indecision, which mainly involves difficulty choosing between options, awkwardness often comes from relational, situational, or consequential tensions that make every option feel somewhat difficult.', true, 62),
('EMO_063', 'EFAM_005', 'Ái ngại', 'Socially uneasy / Concerned', '😬', '#AF85DA', 'Mình thấy ngại và không thật thoải mái vì sợ lời nói, hành động hay tình huống này có thể gây phiền hoặc khiến ai đó khó xử. Khác với ngượng ngùng tập trung vào việc mình bị chú ý, ái ngại hướng nhiều hơn tới sự bất tiện hay khó xử có thể xảy ra giữa người với người.', 'I feel uneasy because something I say, do, or witness might burden someone or create an awkward situation. Unlike embarrassment centered on being noticed myself, this concern focuses more on possible interpersonal discomfort.', true, 63),
('EMO_064', 'EFAM_005', 'Lấn cấn', 'Uneasy', '🌫️', '#9B8AFB', 'Mình cảm thấy có gì đó chưa ổn, chưa đúng hoặc chưa trọn, nhưng chưa xác định rõ vấn đề nằm ở đâu. Nó giống một gợn nhỏ còn ở lại, khiến mình chưa thể hoàn toàn yên lòng dù chưa có một nguy cơ cụ thể.', 'I sense that something is not quite right, settled, or complete, but I cannot yet identify exactly what the issue is. It feels like a small inner disturbance that prevents me from fully relaxing, even without a specific threat.', true, 64),
('EMO_065', 'EFAM_005', 'Phân vân', 'Undecided', '↔️', '#7C6FF6', 'Mình đang nhìn thấy nhiều lựa chọn hoặc nhiều cách hiểu đều có lý, nên sự chú ý cứ đi qua đi lại giữa chúng. Vấn đề không hẳn là mình sợ hành động, mà là mình chưa biết phương án nào phù hợp hơn để chọn.', 'I can see several options or interpretations that each make sense, so my attention keeps moving between them. The difficulty is not necessarily fear of acting; I do not yet know which option fits best.', true, 65),
('EMO_066', 'EFAM_005', 'Do dự', 'Hesitant', '❓', '#9580ED', 'Mình đang đứng gần một lựa chọn hoặc hành động, nhưng một phần vẫn giữ lại vì chưa đủ chắc chắn, an toàn hoặc sẵn sàng. Khác với phân vân giữa nhiều phương án, do dự có thể xảy ra ngay cả khi mình đã biết mình muốn làm gì.', 'I am close to making a choice or taking action, but part of me still holds back because I do not feel certain, safe, or ready enough. Unlike indecision between several options, hesitation can remain even when I already know what I want to do.', true, 66),
('EMO_067', 'EFAM_005', 'Mâu thuẫn', 'Ambivalent', '🌓', '#7B61FF', 'Hai cảm xúc, mong muốn hoặc giá trị trái chiều đang cùng có mặt trong mình. Một phần muốn tiến lại gần trong khi phần khác muốn lùi ra; cả hai phía đều có thể thật và đều cần được lắng nghe.', 'Two opposing feelings, desires, or values are present in me at the same time. One part may want to move closer while another pulls away, and both sides may be real and worthy of attention.', true, 67),
('EMO_068', 'EFAM_005', 'Chênh vênh', 'Unsteady', '🪶', '#8E7DF2', 'Mình thấy lòng thiếu ổn định, như chưa tìm được chỗ đứng giữa điều đang thay đổi. Khác với bơ vơ nghiêng về nỗi buồn không biết dựa vào ai hay đâu, chênh vênh nhấn vào cảm giác mất thăng bằng bên trong.', 'I feel internally unsteady, as though I have not found my footing amid change. Unlike forlornness, which centers on sadness and having nowhere to turn, this emphasizes emotional instability.', true, 68),
('EMO_069', 'EFAM_005', 'Bâng khuâng', 'Wistful', '☁️', '#A78BFA', 'Mình thấy xao xuyến nhẹ và hơi se lòng trước một ký ức, điều đổi thay hoặc khả năng chưa thành. Cảm giác có thể mơ màng và không có đối tượng thật rõ; khác với lưu luyến thường gắn với việc sắp phải rời một điều mình gắn bó.', 'I feel a gentle, wistful ache around a memory, a change, or a possibility that never quite became real. It may be diffuse or dreamy, unlike reluctance to part, which centers more clearly on leaving something I am attached to.', true, 69),
('EMO_070', 'EFAM_005', 'Ngọt ngào xen buồn', 'Bittersweet', '🥲', '#A884F0', 'Niềm vui và nỗi buồn cùng xuất hiện vì chính một điều: nó đẹp và đáng quý, nhưng cũng đang kết thúc, đổi thay hoặc không thể giữ mãi. Hai sắc thái không triệt tiêu nhau; chúng cùng làm trải nghiệm trở nên đầy hơn.', 'Joy and sadness arise together in response to the same experience: it is beautiful and precious, yet it is ending, changing, or cannot be kept forever. Neither feeling cancels the other; together they make the experience feel fuller.', true, 70),
('EMO_071', 'EFAM_005', 'Chộn rộn', 'Fluttery anticipation', '🦋', '#9B7AE8', 'Mình thấy lòng xôn xao, khó yên trước một cuộc gặp, thay đổi hoặc điều sắp tới, mà chưa biết nghiêng về vui hay lo. Khác với háo hức thiên về mong đợi dễ chịu, chộn rộn giữ cả sự rạo rực và chút bồn chồn chưa rõ sắc thái.', 'I feel inwardly stirred and unsettled before an encounter, change, or approaching event, without a clear tilt toward pleasure or worry. Unlike pleasurable eagerness, this combines anticipation with restlessness of uncertain emotional tone.', true, 71),
('EMO_072', 'EFAM_005', 'Ngập ngừng chờ nhau', 'Unspoken anticipation / Mutual hesitation', '👁️', '#A078C9', 'Mình thấy ngập ngừng, mong chờ và có cảm giác giữa hai người đang có một điều chưa ai mở lời. Đây là cảm nhận của mình về khoảnh khắc ấy; không thể từ một ánh nhìn mà khẳng định người kia cũng muốn giống mình.', 'I feel hesitant and expectant, as though something between us remains unspoken and neither person has begun. This describes my perception of the moment, not certainty from a glance that the other person wants what I want.', true, 72),
('EMO_073', 'EFAM_005', 'Bất ngờ', 'Surprised', '😲', '#E56BDE', 'Một điều vừa xảy ra khác với điều mình dự đoán, khiến sự chú ý lập tức dừng lại và hướng về nó. Bất ngờ tự nó chưa hẳn vui hay khó chịu; sắc thái sẽ hình thành sau khi mình hiểu điều vừa xảy ra có ý nghĩa gì.', 'Something differs from what I expected, immediately interrupting and redirecting my attention. Surprise is not inherently pleasant or unpleasant; its emotional tone develops after I interpret what happened.', true, 73),
('EMO_074', 'EFAM_005', 'Kinh ngạc', 'Amazed', '🤯', '#D65DB1', 'Mình thấy kinh ngạc và bị thu hút trước một điều khác thường hoặc vượt xa dự đoán. Khác với ngưỡng mộ hướng vào phẩm chất đáng trân trọng, kinh ngạc nhấn vào mức bất ngờ; điều ấy có thể chưa đủ rộng lớn để thành cảm giác awe.', 'I feel amazed and drawn in by something remarkable or far beyond what I expected. Unlike admiration for a valued quality, amazement emphasizes unexpectedness; the experience need not have the vastness associated with awe.', true, 74),
('EMO_075', 'EFAM_005', 'Sửng sốt', 'Shocked', '⚡', '#B977E3', 'Mình đứng sững hoặc không biết nói gì trong khoảnh khắc nhận một điều quá bất ngờ, khó tin. Khác với choáng váng nhấn vào đầu óc còn lơ mơ, chưa theo kịp sau đó, sửng sốt nhấn vào phản ứng bất ngờ ngay lúc tiếp nhận.', 'I freeze or lose my words at the moment something feels startling or hard to believe. Unlike feeling dazed and mentally slow to catch up afterward, shock here emphasizes the immediate reaction to the news or event.', true, 75),
('EMO_076', 'EFAM_005', 'Choáng váng', 'Dazed / Stunned', '💫', '#B56BDA', 'Mình thấy đầu óc còn lơ mơ hoặc chưa theo kịp sau một tin hay trải nghiệm bất ngờ, như cần thêm thời gian mới hiểu hết. Khác với sửng sốt nhấn vào khoảnh khắc đứng hình ban đầu, choáng váng nhấn vào cảm giác chưa định thần lại; ở đây không dùng để mô tả chóng mặt do cơ thể.', 'I feel mentally dazed or slow to catch up after unexpected news or an experience, as though I need time to take it in. Unlike the immediate freeze of shock, this emphasizes not yet recovering my bearings; it does not refer here to physical dizziness.', true, 76),
('EMO_077', 'EFAM_005', 'Chưng hửng', 'Taken Aback / Deflated', '😶', '#C47AD9', 'Một điều vừa xảy ra khác với điều mình đang chờ đợi hoặc chuẩn bị tinh thần, khiến mình khựng lại và hơi hụt xuống trong chốc lát. Khác với bất ngờ chỉ vì điều không dự đoán trước, chưng hửng thường có thêm một chút hụt hẫng vì mạch kỳ vọng vừa bị ngắt.', 'Something happens differently from what I was expecting or mentally prepared for, leaving me momentarily stopped and deflated. Unlike simple surprise at the unexpected, being taken aback often carries some disappointment because an anticipated course of events has been interrupted.', true, 77),
('EMO_078', 'EFAM_005', 'Lạ lẫm', 'Unfamiliar', '🛸', '#8A5CF6', 'Mình cảm thấy chưa quen trước một người, nơi hoặc trải nghiệm mới, nên quan sát và dò nhịp nhiều hơn. Khác với hoang mang có nỗi lo và mất định hướng, lạ lẫm chỉ mô tả sự xa lạ đang cảm nhận và có thể đi cùng tò mò.', 'I feel unfamiliar with a person, place, or experience and spend more attention finding my bearings. Unlike distressed bewilderment, unfamiliarity need not involve worry and may accompany curiosity.', true, 78),
('EMO_079', 'EFAM_005', 'Lạc nhịp nơi xa lạ', 'Feeling out of place / Dépaysement', '🧳', '#7E88AE', 'Mình thấy lạc nhịp khi ở một môi trường khác hẳn điều quen thuộc, như những dấu hiệu thường giúp mình định hướng không còn ở đó. Khác với lạ lẫm trước một điều mới riêng lẻ, trải nghiệm này gắn với việc rời cả bối cảnh quen và có thể pha tò mò hoặc khó chịu.', 'I feel out of place in an environment unlike the familiar one, as though my usual orienting cues are missing. Unlike unfamiliarity with one new thing, this concerns displacement from a familiar setting and may mix curiosity with discomfort.', true, 79),
('EMO_080', 'EFAM_005', 'Mất phương hướng', 'Directionless', '🧭', '#6B7280', 'Mình chưa nhìn thấy điều gì đáng để hướng tới hoặc bước tiếp theo nào có ý nghĩa. Không chỉ thiếu thông tin, mình còn cảm thấy các lựa chọn hiện tại chưa kết nối được với một phương hướng thật sự thuộc về mình.', 'I cannot see what is worth moving toward or which next step would feel meaningful. The problem is not only a lack of information; the available options do not yet connect with a direction that feels genuinely mine.', true, 80),
('EMO_081', 'EFAM_006', 'Lo lắng', 'Worried', '😟', '#FF9F43', 'Tâm trí mình đang hướng về những điều không mong muốn có thể xảy ra và cố dự đoán, chuẩn bị hoặc ngăn chúng lại. Mình thường biết tương đối rõ mình đang lo về việc gì, dù chưa biết khả năng nó xảy ra đến đâu.', 'My mind is focused on unwanted possibilities and keeps trying to predict, prepare for, or prevent them. I usually know what I am worried about, even when the actual likelihood remains uncertain.', true, 81),
('EMO_082', 'EFAM_006', 'Bất an', 'Anxious', '🫨', '#F8961E', 'Mình thấy không yên và khó thả lỏng vì có cảm giác điều gì đó có thể không ổn, đôi khi chưa rõ mình lo về điều gì. Khác với cảnh giác là tập trung quan sát nguy cơ, bất an nhấn vào sự căng và lo đang ở bên trong.', 'I feel unsettled and unable to relax because something might be wrong, sometimes without knowing exactly what. Unlike wariness, which emphasizes watchful caution, anxiety centers on the unease I am experiencing.', true, 82),
('EMO_083', 'EFAM_006', 'Hồi hộp', 'Nervous', '🫀', '#F9844A', 'Mình cảm thấy tim hoặc nhịp bên trong rộn lên trước một việc sắp diễn ra, thường kèm lo về kết quả hoặc cách mình sẽ thể hiện. Háo hức thiên về vui mong chờ; hồi hộp có thêm sự căng vì chưa biết chuyện sẽ ra sao.', 'I feel keyed up before an event, often with concern about the outcome or how I will perform. Eagerness leans toward pleasurable anticipation; nervousness includes tension about how things will turn out.', true, 83),
('EMO_084', 'EFAM_006', 'Bồn chồn', 'Restless', '🌀', '#F9C74F', 'Năng lượng trong mình không tìm được chỗ yên, khiến mình khó ngồi lại hoặc liên tục muốn làm, đổi tư thế hay kiểm tra một điều gì đó. Mình cảm thấy bị thúc từ bên trong nhưng chưa chắc biết hành động nào thật sự sẽ giúp.', 'My energy cannot settle, making it difficult to stay still and creating repeated urges to move, act, shift position, or check something. I feel internally driven without necessarily knowing what action would actually help.', true, 84),
('EMO_085', 'EFAM_006', 'Nôn nóng', 'Impatient', '😒', '#F59E0B', 'Mình thấy khó chịu với việc phải chờ hoặc với tốc độ đang diễn ra, và muốn nó nhanh lên. Khác với háo hức là vui mong chờ, nôn nóng có điểm chính là sự sốt ruột, khó chịu trước chậm trễ.', 'I feel irritated by waiting or by the pace of events and want things to move faster. Unlike eagerness, which centers on pleasurable anticipation, impatience centers on discomfort with delay.', true, 85),
('EMO_086', 'EFAM_006', 'Sốt ruột', 'Anxiously Impatient / Antsy', '⏳', '#F5A13F', 'Mình đang chờ một việc xảy ra hoặc có kết quả nhưng càng chờ càng khó yên, vừa muốn nó diễn ra nhanh hơn vừa có chút lo về điều sẽ xảy đến. Khác với nôn nóng thiên về muốn tiến nhanh, sốt ruột thường có thêm sự bất an trong lúc chờ.', 'I am waiting for something to happen or resolve, but the waiting makes it increasingly difficult to settle, combining impatience with some anxiety about the outcome. Unlike simple eagerness to move faster, anxious impatience contains a clearer sense of unease while waiting.', true, 86),
('EMO_087', 'EFAM_006', 'Cảnh giác', 'Wary / Guarded', '👁️', '#D99531', 'Mình thấy dè chừng và khó hoàn toàn thả lỏng, nên quan sát kỹ trước khi tin hay tiến gần. Khác với sợ hãi trước mối đe dọa mình đã nhận thấy, cảnh giác có thể xuất hiện khi chỉ mới nghi có điều không ổn; nó không khẳng định nguy cơ chắc chắn tồn tại.', 'I feel cautious and guarded, watching carefully before trusting or approaching. Unlike fear in response to a perceived threat, wariness can arise when I only suspect something may be wrong; it does not establish that danger exists.', true, 87),
('EMO_088', 'EFAM_006', 'Sợ hãi', 'Afraid', '😨', '#FF6B35', 'Mình cảm thấy sợ trước một mối đe dọa mà mình đang nhận thấy hoặc hình dung, và muốn bảo vệ bản thân hay tránh nó. Điểm chính là nỗi sợ lúc này; cảm giác đó không tự chứng minh rằng nguy hiểm chắc chắn có thật.', 'I feel fear in response to a threat I perceive or imagine, with an impulse to protect myself or avoid it. This describes my current fear and does not by itself establish that the danger is real.', true, 88),
('EMO_089', 'EFAM_006', 'Sợ điều sắp đến', 'Dread', '🌑', '#D97706', 'Một nỗi sợ nặng đang phủ lên điều mình biết hoặc tin rằng sắp phải đối diện. Chỉ nghĩ đến nó cũng khiến mình muốn trì hoãn, tránh né hoặc ước rằng khoảng thời gian phía trước đừng đến.', 'A heavy fear hangs over something I expect to face. Even thinking about it may make me want to delay, avoid, or wish that the approaching moment would not arrive.', true, 89),
('EMO_090', 'EFAM_006', 'Sợ bỏ lỡ', 'Fear of Missing Out / FOMO', '👀', '#F19B45', 'Mình lo rằng một trải nghiệm, cơ hội hoặc điều đáng giá đang diễn ra mà mình không có mặt, không theo kịp hoặc không được tham gia. Khác với ghen hay đố kỵ tập trung vào điều người khác có, sợ bỏ lỡ tập trung vào khả năng mình đang mất một cơ hội hoặc trải nghiệm quan trọng.', 'I worry that a worthwhile experience, opportunity, or event is happening without me, and that I may miss out or fall behind. Unlike jealousy or envy, which focus more on what someone else has, FOMO centers on the possibility of missing an important opportunity or experience.', true, 90),
('EMO_091', 'EFAM_006', 'Lo thời gian đang khép lại', 'Fear Time Is Running Out / Torschlusspanik', '⌛', '#E77B32', 'Mình lo rằng khoảng thời gian để thực hiện một điều quan trọng đang dần hết và một cơ hội, giai đoạn hoặc cánh cửa nào đó có thể sắp đóng lại. Khác với sợ bỏ lỡ một trải nghiệm đang diễn ra, cảm giác này hướng vào việc mình thấy quỹ thời gian hoặc cơ hội của cả một giai đoạn đang thu hẹp.', 'I feel anxious that the time available to do something important is running out and that an opportunity, life stage, or possibility may soon close. Unlike FOMO about an experience happening without me, this centers on a shrinking window of time or opportunity.', true, 91),
('EMO_092', 'EFAM_006', 'Ghen', 'Jealous', '💚', '#65A30D', 'Mình thấy lo, đau hoặc giận khi cảm nhận vị trí hay sự gần gũi trong một mối quan hệ có thể bị đe dọa bởi người khác. Khác với đố kỵ là muốn điều người kia có, ghen nhấn vào nguy cơ mất mối gắn bó; cảm giác ấy không chứng minh đã có phản bội.', 'I feel fear, hurt, or anger when my place or closeness in a valued relationship seems threatened by someone else. Unlike envy of what another person has, jealousy centers on possible loss and does not prove betrayal.', true, 92),
('EMO_093', 'EFAM_006', 'Hoang mang', 'Bewildered / Disconcerted', '😰', '#EE914D', 'Mình vừa thấy lo vừa không biết nên hiểu hay dựa vào điều gì khi tình hình thay đổi hoặc các điểm tựa trở nên không rõ. Khác với bối rối chủ yếu là rối trong cách hiểu, hoang mang có thêm nỗi bất an; không nhất thiết dữ dội hay khẩn cấp như hoảng loạn.', 'I feel both unsettled and unsure how to make sense of things or what to rely on. Unlike confusion alone, bewilderment here includes anxiety; it need not have the intensity or urgency of panic.', true, 93),
('EMO_094', 'EFAM_006', 'Áp lực', 'Pressured', '🧱', '#F3722C', 'Mình cảm thấy bị thúc bởi kỳ vọng, trách nhiệm hoặc thời hạn, như có điều mình phải đáp ứng. Áp lực có thể xuất hiện dù mình vẫn xử lý được; quá tải là khi lượng việc, thông tin hoặc cảm xúc đã vượt mức mình thấy có thể tiếp nhận.', 'I feel pushed by expectations, responsibilities, or deadlines, as though I must meet a demand. Pressure can be present while I still feel capable; overwhelm emphasizes having more to process than I feel able to handle.', true, 94),
('EMO_095', 'EFAM_006', 'Căng thẳng', 'Stressed', '🪢', '#FF7F50', 'Cơ thể và tâm trí mình đang giữ chặt để đáp ứng, kiểm soát hoặc phòng vệ trước điều đang diễn ra. Mình có thể vẫn hoạt động được, nhưng phải tiêu tốn nhiều sức để duy trì sự tập trung và không để mọi thứ vượt khỏi tầm tay.', 'My body and mind are tightening in order to cope, control, or defend against what is happening. I may still be functioning, but it takes significant effort to stay focused and keep things from slipping beyond my control.', true, 95),
('EMO_096', 'EFAM_006', 'Ngột ngạt', 'Stifled / Suffocated', '😮‍💨', '#E98A4A', 'Mình cảm thấy như không còn đủ khoảng trống để thở, suy nghĩ hoặc là chính mình trước áp lực, tình huống hoặc môi trường đang bao quanh. Khác với quá tải vì có quá nhiều thứ phải xử lý, ngột ngạt nhấn vào cảm giác bị bó chặt và thiếu không gian bên trong hoặc xung quanh mình.', 'I feel as though there is not enough room to breathe, think, or be myself under the pressure of my current situation or environment. Unlike overwhelm from having too much to process, feeling stifled centers on constriction and lack of psychological or physical space.', true, 96),
('EMO_097', 'EFAM_006', 'Quá tải', 'Overwhelmed', '🌪️', '#F94144', 'Mình cảm thấy có quá nhiều việc, thông tin, kích thích hoặc cảm xúc cùng lúc để tiếp nhận và sắp xếp. Khác với áp lực là cảm giác phải đáp ứng, quá tải nhấn vào việc khả năng xử lý của mình đang không theo kịp lượng đang đến.', 'I feel there is too much work, information, stimulation, or emotion to take in and organize at once. Unlike pressure to meet a demand, overwhelm emphasizes that my processing capacity cannot keep up with what is arriving.', true, 97),
('EMO_098', 'EFAM_006', 'Hoảng hốt', 'Alarmed', '🚨', '#E85D04', 'Mình giật mình sợ hãi và lập tức chú ý đến một dấu hiệu khiến mình nghĩ cần phản ứng nhanh. Khác với sửng sốt vì điều quá bất ngờ, hoảng hốt có cảm giác báo động về nguy cơ; khác với hoảng loạn, mình có thể vẫn định hướng được.', 'I experience a sudden burst of fear and attention toward something that seems to require an urgent response. Unlike shock at an unexpected event, alarm includes a sense of threat; unlike panic, I may still be able to orient myself.', true, 98),
('EMO_099', 'EFAM_006', 'Hoảng loạn', 'Panicked', '🆘', '#EF4444', 'Nỗi sợ dâng lên rất mạnh khiến mình khó nghĩ rõ và có cảm giác phải thoát ra ngay. Đây là cách gọi trải nghiệm sợ hãi dữ dội trong lần check-in, không phải kết luận rằng mình có một rối loạn hay một cơn hoảng sợ lâm sàng.', 'Fear feels so intense that thinking clearly becomes difficult and I feel an urgent need to escape. This labels a current experience of intense fear, not a diagnosis of a disorder or a clinical panic attack.', true, 99),
('EMO_100', 'EFAM_006', 'Bất lực', 'Helpless', '🆘', '#EBA449', 'Mình muốn thay đổi, ngăn lại hoặc bảo vệ một điều quan trọng nhưng hiện chưa nhìn thấy khả năng, quyền lực hay nguồn lực để làm được. Điều đau nhất không chỉ là tình huống khó, mà là cảm giác mình không thể tạo ra khác biệt vào lúc này.', 'I want to change, prevent, or protect something important, but I cannot currently see enough ability, power, or resources to do so. The pain lies not only in the situation itself, but in feeling unable to make a difference right now.', true, 100),
('EMO_101', 'EFAM_007', 'Cáu kỉnh', 'Irritable / Irritated', '😒', '#FF7B72', 'Mình dễ thấy khó chịu trước tiếng động, lời nói hoặc bất tiện nhỏ, như thể ngưỡng chịu đựng đang thấp hơn thường ngày. Khác với bực bội vì một việc bị cản trở, cáu kỉnh có thể lan ra nhiều chuyện nhỏ mà không có một mục tiêu cụ thể.', 'I feel easily irritated by small noises, comments, or inconveniences, as though my tolerance is lower than usual. Unlike frustration at a blocked goal, irritability may spread across minor things without one specific target.', true, 101),
('EMO_102', 'EFAM_007', 'Bực bội', 'Frustrated', '😤', '#FF6B6B', 'Mình muốn tiến tới một kết quả nhưng đang bị cản, trì hoãn hoặc phải thử đi thử lại mà vẫn chưa được. Năng lượng muốn hành động vẫn còn đó, nhưng nó đang liên tục va vào một vật cản.', 'I am trying to reach an outcome but feel blocked, delayed, or repeatedly unsuccessful. The energy to act remains, but it keeps colliding with an obstacle.', true, 102),
('EMO_103', 'EFAM_007', 'Ngán ngẩm', 'Fed up', '🙄', '#E76561', 'Mình thấy vừa chán vừa bực vì một chuyện khó chịu hoặc thất vọng đã lặp lại đến mức trong lòng bật lên «đủ rồi». Khác với chán vì thiếu hấp dẫn, ngán ngẩm có sự phản đối; khác với oán giận, nó không nhất thiết gắn với một tổn thương hay bất công cũ.', 'I feel bored and irritated by something unpleasant or disappointing that has repeated until I feel ''enough already''. Unlike boredom alone, being fed up includes protest; unlike resentment, it need not center on an old hurt or injustice.', true, 103),
('EMO_104', 'EFAM_007', 'Hờn dỗi', 'Hurt and sulky', '😾', '#ED7181', 'Mình thấy giận xen chạnh lòng vì không được đáp lại như mong, và có phần muốn im đi hoặc tỏ ra không vui. Khác với oán giận giữ một bất mãn lâu dài, hờn dỗi thường gắn gần với một chuyện trong quan hệ; cảm xúc này không bắt buộc mình phải lạnh nhạt hay thử lòng ai.', 'I feel hurt and annoyed after not receiving the response I hoped for, with an impulse to go quiet or show displeasure. Unlike a sustained grievance, this is often tied to a nearby relational incident and does not require me to withdraw or test someone.', true, 104),
('EMO_105', 'EFAM_007', 'Ấm ức', 'Aggrieved', '😣', '#E63946', 'Mình thấy giận xen tủi vì cho rằng mình chịu điều không đúng mà chưa nói được hoặc chưa được nghe đầy đủ. Khác với hờn dỗi thường gắn với một hụt hẫng trong quan hệ, ấm ức nhấn vào cảm giác bị oan hoặc chịu thiệt còn nghẹn lại.', 'I feel anger mixed with hurt because I believe I have been wronged but cannot fully express it or feel heard. Unlike a relational sulk, this emphasizes an unspoken sense of injustice or unfair treatment.', true, 105),
('EMO_106', 'EFAM_007', 'Tức giận', 'Angry', '🔥', '#FF4D4F', 'Mình cảm thấy nóng giận hoặc có lực muốn phản đối trước điều mình cho là gây hại, xem nhẹ hay vượt quá giới hạn. Đây là phản ứng cảm xúc của mình; nó không tự xác nhận ai đúng, ai sai hoặc bắt buộc mình phải hành động theo cơn giận.', 'I feel anger and an impulse to object to something I perceive as harmful, dismissive, or overstepping a boundary. The feeling does not by itself establish who is right or require me to act on it.', true, 106),
('EMO_107', 'EFAM_007', 'Bất bình', 'Indignant', '⚖️', '#D90429', 'Mình phản ứng trước điều mà mình cho là bất công, thiếu tôn trọng hoặc đi ngược một nguyên tắc quan trọng. Cảm giác này mang theo một nhận định rõ rằng điều đó không nên được xem là bình thường hay dễ dàng bỏ qua.', 'I react to something I see as unfair, disrespectful, or contrary to an important principle. Indignation carries a clear sense that the situation should not be normalized or casually dismissed.', true, 107),
('EMO_108', 'EFAM_007', 'Phẫn nộ', 'Outraged', '🌋', '#C1121F', 'Một cơn giận rất mạnh đang xuất hiện trước điều mình xem là nghiêm trọng, tàn nhẫn hoặc hoàn toàn không thể chấp nhận. Mình không chỉ muốn phản đối; mình cảm thấy một giá trị căn bản đang bị chà đạp và cần được bảo vệ quyết liệt.', 'I feel an intense anger toward something I regard as grave, cruel, or wholly unacceptable. I do not merely object; I feel that a fundamental value has been violated and demands forceful protection.', true, 108),
('EMO_109', 'EFAM_007', 'Oán giận', 'Resentful', '🌶️', '#D00000', 'Cơn giận quay lại khi mình nhớ một tổn thương hay điều mình xem là bất công chưa được giải quyết. Khác với ngán ngẩm vì một chuyện lặp lại đã quá đủ, oán giận bám rõ hơn vào một vết thương hoặc món nợ tình cảm còn giữ trong lòng.', 'Anger returns when I remember a hurt or perceived injustice that still feels unresolved. Unlike being fed up with repeated frustration, resentment is more closely tied to a lingering grievance or emotional debt.', true, 109),
('EMO_110', 'EFAM_007', 'Ghê tởm', 'Disgusted', '🤢', '#F97316', 'Mình cảm nhận một thứ là bẩn, ô nhiễm, sai trái hoặc không thể tiếp nhận và muốn tránh xa hay loại bỏ nó. Phản ứng này có thể được khơi lên bởi mùi vị, hình ảnh, hành vi hoặc một vi phạm đạo đức sâu.', 'I perceive something as contaminated, offensive, morally repellent, or impossible to take in, creating an urge to reject or move away from it. The response may be triggered by sensory input, behavior, or a profound moral violation.', true, 110),
('EMO_111', 'EFAM_007', 'Khinh miệt', 'Contemptuous', '👎', '#C95F2C', 'Mình mất sự tôn trọng và nhìn một người hoặc hành vi như thấp kém, không xứng đáng hoặc không đáng được xem ngang hàng. Cảm xúc này thường lạnh hơn tức giận và tạo ra khoảng cách rõ hơn giữa mình với đối tượng.', 'I lose respect and view a person or behavior as inferior, unworthy, or beneath equal regard. Contempt is often colder than anger and creates a stronger interpersonal distance.', true, 111),
('EMO_112', 'EFAM_008', 'Buồn', 'Sad', '😢', '#4D96FF', 'Mình thấy lòng trĩu xuống, se lại hoặc muốn chậm lại trước điều không như mong, điều vắng đi, hay đôi khi chưa rõ nguyên nhân. Buồn không nhất thiết phải có một mất mát lớn; đau buồn vì mất mát là trải nghiệm gắn cụ thể hơn với một điều đã mất.', 'I feel downhearted, aching, or inclined to slow down, perhaps around disappointment or absence, and sometimes without a clear cause. Sadness does not require a major loss; grief is more specifically connected to loss.', true, 112),
('EMO_113', 'EFAM_008', 'Xót xa', 'Sorrowful / Tenderly pained', '💙', '#597BD1', 'Mình thấy đau se lòng và thương trước một nỗi khó, mất mát hoặc điều đáng tiếc đang chứng kiến hay nghĩ tới. Khác với trắc ẩn nhấn thêm vào ý muốn chăm sóc, xót xa nhấn vào nỗi đau thương ấy; mình không cần trực tiếp là người chịu mất mát.', 'I feel a tender, sorrowful ache at suffering, loss, or something regrettable that I witness or think about. Unlike compassion''s additional orientation toward care, this emphasizes the ache itself; the loss need not be mine.', true, 113),
('EMO_114', 'EFAM_008', 'Tủi thân', 'Hurt and overlooked', '😞', '#6C8AE4', 'Mình thấy buồn và chạnh lòng vì có cảm giác mình không được để tâm như từng mong ở một người quan trọng. Khác với bơ vơ là không biết dựa vào đâu, tủi thân nhấn vào nỗi đau «mình không được nghĩ tới», dù chưa biết người kia thật sự nghĩ gì.', 'I feel hurt and sorrowful because it seems that someone important has not cared for me as I hoped. Unlike forlornness about having nowhere to turn, this centers on feeling overlooked without claiming to know the other person''s intentions.', true, 114),
('EMO_115', 'EFAM_008', 'Thất vọng', 'Disappointed', '📉', '#457B9D', 'Điều mình kỳ vọng ở một kết quả, một người hoặc chính mình đã không được đáp lại. Năng lượng từng hướng tới tương lai bỗng hạ xuống vì thực tế không giống điều mình đã tin, chuẩn bị hoặc hy vọng.', 'An expectation I held about an outcome, another person, or myself has not been met. The energy once directed toward the future drops as reality diverges from what I believed, prepared for, or hoped.', true, 115),
('EMO_116', 'EFAM_008', 'Hụt hẫng', 'Let down', '🫗', '#6F8EDB', 'Mình thấy trống và rơi nhịp khi điều mình đã chờ đợi, quen có hoặc gần như tin là sẽ có bỗng không còn. Khác với thất vọng về kết quả không như mong, hụt hẫng nhấn vào khoảng trống đột ngột mà sự thiếu vắng ấy để lại.', 'I feel a hollow drop when something I expected, relied on, or was used to suddenly is not there. Unlike disappointment about an unmet outcome, feeling let down emphasizes the sudden gap its absence leaves.', true, 116),
('EMO_117', 'EFAM_008', 'Vỡ mộng', 'Disillusioned', '🫥', '#5B78D6', 'Không chỉ một kết quả làm mình thất vọng; cả niềm tin, hình ảnh đẹp hoặc câu chuyện mình từng đặt vào một người hay một tương lai đang không còn đứng vững. Mình phải đối diện với khoảng cách giữa điều mình từng tin và điều thực tế vừa cho thấy.', 'It is not only an outcome that disappoints me; a larger belief, idealized image, or story I held about a person or future no longer stands. I am confronting the gap between what I believed and what reality has revealed.', true, 117),
('EMO_118', 'EFAM_008', 'Đau lòng', 'Heartbroken', '🥀', '#3B82F6', 'Mình cảm thấy đau sâu về tình cảm trước tổn thương, xa cách hoặc một chuyện liên quan đến người hay điều mình yêu quý. Xót xa có thể là đau thương khi chứng kiến nỗi khó của người khác; đau lòng ở đây nhấn vào vết đau đang chạm trực tiếp đến tình cảm của mình.', 'I feel deep emotional pain around hurt, distance, or something affecting a person or bond I cherish. A sorrowful ache may arise while witnessing another''s suffering; heartbreak here emphasizes pain that directly touches my own affection or attachment.', true, 118),
('EMO_119', 'EFAM_008', 'Đau buồn vì mất mát', 'Grieving', '🕯️', '#277DA1', 'Mình đang đi qua sự mất đi của một người, mối quan hệ, vai trò, tương lai hoặc phần đời từng có ý nghĩa sâu sắc. Nỗi đau có thể đến thành nhiều đợt và chứa cả buồn, giận, nhớ, trống trải hoặc khó tin rằng điều ấy thật sự đã đổi khác.', 'I am living through the loss of a person, relationship, role, future, or meaningful part of life. Grief may arrive in waves and contain sadness, anger, longing, emptiness, or difficulty accepting that life has truly changed.', true, 119),
('EMO_120', 'EFAM_008', 'Cô đơn', 'Lonely', '🌌', '#577590', 'Mình cảm thấy một khoảng cách buồn giữa sự gần gũi mình đang có và điều mình mong được trải nghiệm. Cảm giác này có thể xuất hiện cả khi ở giữa nhiều người; nó là nỗi cô đơn hiện tại, không chỉ là lời nói về nhu cầu kết nối.', 'I feel a painful gap between the closeness I experience and the closeness I long for. This can happen even among many people; it describes present loneliness rather than simply naming a need for connection.', true, 120),
('EMO_121', 'EFAM_008', 'Bơ vơ', 'Forlorn / Adrift', '🥺', '#6A87BF', 'Mình thấy buồn và nhỏ bé, như không biết nên hướng về ai hay đâu để cảm thấy có điểm tựa. Khác với cô đơn chủ yếu là nỗi thiếu gần gũi, bơ vơ có thêm cảm giác bị bỏ lại giữa một hoàn cảnh mình chưa biết nương vào đâu.', 'I feel sorrowful and vulnerable, unsure whom or where to turn to for a sense of anchoring. Unlike loneliness centered on missing closeness, forlornness also carries the feeling of being left adrift in a situation.', true, 121),
('EMO_122', 'EFAM_008', 'Trống vắng sau cuộc sum vầy', 'Post-Gathering Emptiness / Awumbuk', '🪑', '#667788', 'Sau khi một cuộc gặp gỡ, chuyến thăm hoặc khoảng thời gian đông vui kết thúc, mình cảm thấy không gian và bên trong mình bỗng trống hơn bình thường. Khác với cô đơn có thể xuất hiện bất cứ lúc nào, cảm giác này được tạo nên rõ rệt bởi sự tương phản giữa lúc vừa có nhiều kết nối và sự vắng lặng ngay sau đó.', 'After a gathering, visit, or lively period ends, both the space around me and my inner experience suddenly feel emptier than usual. Unlike loneliness, which can arise at any time, this feeling is shaped by the contrast between recent togetherness and the quiet that follows.', true, 122),
('EMO_123', 'EFAM_008', 'Nhớ nhung', 'Longing', '💭', '#4895EF', 'Mình thấy một nỗi nhớ kéo về người, nơi hoặc trải nghiệm đang vắng mặt, kèm mong muốn được gần lại. Khác với lưu luyến lúc đang rời đi, nhớ nhung thường rõ khi khoảng cách đã hiện hữu; hoài niệm có thể ấm áp mà không nhất thiết muốn quay lại.', 'I feel an ache toward an absent person, place, or experience and wish to be close again. Unlike reluctance to part during a goodbye, longing becomes prominent after distance is present; fond nostalgia need not include a wish to return.', true, 123),
('EMO_124', 'EFAM_008', 'Nhớ thương khắc khoải', 'Melancholic longing / Saudade', '🌙', '#4F6FAE', 'Mình thấy một nỗi nhớ sâu về người, nơi hay thời đã xa, vừa ấm vì từng gắn bó vừa buồn vì không có ở đây. Khác với lưu luyến lúc sắp rời đi, nỗi nhớ này hướng về sự vắng mặt đã có và có thể kèm cảm giác khó trở lại như xưa.', 'I feel a deep longing for an absent person, place, or time, with warmth for the bond and sadness about its absence. Unlike reluctance to part during a goodbye, this concerns an existing absence and may include a sense that things cannot return as they were.', true, 124),
('EMO_125', 'EFAM_008', 'Nhớ một chốn không thể trở về', 'Longing for a Place One Cannot Return To / Hiraeth', '🌄', '#5E7FD8', 'Mình nhớ một nơi, một mái nhà, một thời kỳ hoặc cảm giác từng thuộc về đâu đó, nhưng đồng thời biết rằng mình không thể thật sự quay lại nơi ấy như nó từng tồn tại. Khác với nhớ nhung thông thường, cảm giác này chứa cả sự gắn bó, mất mát và ý thức rằng điều mình nhớ có thể đã thay đổi hoặc không còn nữa.', 'I long for a place, home, period, or sense of belonging while knowing that I cannot truly return to it as it once was. Unlike ordinary longing, this feeling combines attachment with loss and the awareness that what I miss may have changed or no longer exist.', true, 125),
('EMO_126', 'EFAM_008', 'Hoài niệm ấm áp', 'Fond nostalgia / Natsukashii', '🎞️', '#6F86C5', 'Một ký ức hay điều quen thuộc gợi mình nhớ lại quá khứ với cảm giác ấm áp và trìu mến. Khác với nhớ nhung thiên về muốn gần lại điều đang vắng, mình có thể vui vì đã từng có điều ấy mà không cần quay lại.', 'A memory or familiar cue brings back the past with warmth and affection. Unlike longing to be close to something absent, I may appreciate having experienced it without needing to return.', true, 126),
('EMO_127', 'EFAM_008', 'Tiếc nuối', 'Regretful', '🍂', '#3A86FF', 'Mình nhìn lại một lựa chọn, cơ hội hoặc khả năng đã qua và ước rằng mọi chuyện từng có thể khác. Cảm giác này không nhất thiết nói rằng mình đã làm điều sai; đôi khi mình chỉ đang buồn cho một con đường không còn có thể quay lại.', 'I look back on a choice, opportunity, or possibility and wish things could have been different. This does not necessarily mean that I did something wrong; I may simply be mourning a path that can no longer be taken.', true, 127),
('EMO_128', 'EFAM_008', 'Xao lòng trước vô thường', 'Moved by impermanence / Mono no aware', '🍃', '#8D86C9', 'Mình thấy lòng vừa nâng niu vừa se lại khi nhận ra một điều đẹp đang đổi thay và không thể giữ mãi. Khác với nhớ nhung điều đã vắng mặt, trọng tâm là sự mong manh của khoảnh khắc đang có; trong Sắc Ký, đây là một cách diễn đạt trải nghiệm được gợi từ mono no aware.', 'I feel tenderly moved by the fragility of something beautiful that is changing and cannot last. Unlike longing for an absence, this centers on impermanence within the present; in Sắc Ký, it is an experience label inspired by mono no aware.', true, 128),
('EMO_129', 'EFAM_009', 'Ngượng ngùng', 'Embarrassed', '☺️', '#CC89ED', 'Mình ý thức rõ về bản thân sau một khoảnh khắc vụng về, bị chú ý hoặc không biết phải phản ứng thế nào cho tự nhiên. Cảm giác này thường nhẹ và ngắn hơn xấu hổ, và mình vẫn có thể nhìn lại nó với chút hài hước khi tình huống qua đi.', 'I become acutely self-conscious after an awkward moment, unexpected attention, or uncertainty about how to respond naturally. Embarrassment is usually lighter and more temporary than shame, and I may later be able to see the moment with some humor.', true, 129),
('EMO_130', 'EFAM_009', 'Xấu hổ', 'Ashamed', '🙈', '#C77DFF', 'Mình cảm thấy muốn giấu đi hoặc thu nhỏ lại vì nhìn bản thân là đáng chê, không đủ tốt hoặc khó được chấp nhận. Khác với tội lỗi tập trung vào một hành động, xấu hổ dễ lan thành đánh giá về chính con người mình; cảm giác đó không chứng minh mình thật sự kém giá trị.', 'I feel like hiding or shrinking because I see myself as inadequate, unacceptable, or worthy of criticism. Unlike guilt about an action, shame spreads toward my sense of self; it does not prove that I am less worthy.', true, 130),
('EMO_131', 'EFAM_009', 'Nhục nhã', 'Humiliated', '😳', '#8F5BD7', 'Mình thấy đau, hổ thẹn hoặc giận vì cảm giác phẩm giá bị hạ thấp, chẳng hạn khi bị làm bẽ mặt hay xem thường. Khác với xấu hổ nảy từ cách tự nhìn mình, nhục nhã gắn rõ hơn với trải nghiệm bị người khác đối xử hạ thấp.', 'I feel hurt, shame, or anger because my dignity seems to have been diminished, for example through ridicule or disrespect. Unlike shame arising from self-evaluation, humiliation is more closely tied to experiencing degrading treatment.', true, 131),
('EMO_132', 'EFAM_009', 'Áy náy', 'Guilty Unease', '😥', '#C779B9', 'Mình thấy trong lòng chưa yên vì nghĩ rằng mình có thể đã làm, nói hoặc bỏ sót điều gì đó khiến người khác bị ảnh hưởng. Khác với tội lỗi mạnh hơn và thường đi kèm phán xét rõ về bản thân, áy náy thường nhẹ hơn, dai dẳng và mang cảm giác “có gì đó chưa ổn”.', 'I feel uneasy because I think something I did, said, or failed to do may have affected someone negatively. Unlike stronger guilt, which often involves a clearer judgment of oneself, guilty unease is usually lighter, lingering, and carries a sense that something is not quite right.', true, 132),
('EMO_133', 'EFAM_009', 'Tội lỗi', 'Guilty', '🧩', '#B565D9', 'Mình thấy cắn rứt vì cho rằng điều mình đã làm hoặc bỏ sót có thể trái với giá trị hay gây ảnh hưởng không mong muốn. Trọng tâm là hành động và trách nhiệm mình cảm nhận, không phải phán xét toàn bộ bản thân; cảm giác tội lỗi không tự chứng minh mình có lỗi.', 'I feel troubled because I believe something I did or failed to do may conflict with my values or have caused harm. The focus is my perceived action and responsibility, not my whole self; feeling guilty does not by itself prove fault.', true, 133),
('EMO_134', 'EFAM_009', 'Hối hận', 'Remorseful', '↩️', '#9D4EDD', 'Mình thấy đau và ân hận khi nghĩ về một việc mình tin đã gây tổn thương, kèm mong muốn đã làm khác hoặc có thể sửa chữa. Khác với tiếc nuối về một cơ hội đã qua, hối hận thường có thêm phần trách nhiệm mà mình nhận về hành động của mình.', 'I feel regret and sorrow over an action I believe caused harm, with a wish to have acted differently or to make amends. Unlike regret over a missed opportunity, remorse usually includes felt responsibility for my own action.', true, 134),
('EMO_135', 'EFAM_009', 'Tự trách', 'Self-blaming', '🪞', '#B185DB', 'Mình thấy nặng nề khi liên tục quay lỗi và lời phán xét vào bản thân về điều đã xảy ra. Đây là trạng thái tự phê phán đi kèm cảm xúc khó chịu, không phải bằng chứng mọi chuyện đều do mình hay là một cảm xúc đơn lẻ như tội lỗi.', 'I feel weighed down as I repeatedly direct blame and criticism at myself over what happened. This is an emotionally painful self-evaluative state, not proof that everything is my fault or a single emotion identical to guilt.', true, 135),
('EMO_136', 'EFAM_009', 'Sợ mình mờ nhạt', 'Fear of an unremarkable life', '🪞', '#D77A22', 'Mình thấy lo hoặc sợ khi nghĩ mình đang quá bình thường, dễ bị quên hoặc không để lại dấu ấn như mong. Đây là nỗi lo về sự mờ nhạt đang trải nghiệm, không phải kết luận đời mình vô nghĩa hay tên của một rối loạn.', 'I feel worried or afraid at the thought of being ordinary, forgotten, or less distinctive than I hoped. This names a present fear of insignificance, not a verdict that my life lacks meaning or the name of a disorder.', true, 136),
('EMO_137', 'EFAM_009', 'Đố kỵ', 'Envious', '🟢', '#84CC16', 'Mình thấy nhói hoặc khó chịu khi so sánh với điều người khác có mà mình cũng muốn. Khác với ngưỡng mộ là trân trọng phẩm chất của họ, đố kỵ có thêm nỗi đau vì phần mình cảm thấy thiếu; khác với ghen là lo mất một mối quan hệ đang có.', 'I feel a painful comparison with something another person has that I also want. Unlike admiration, envy includes discomfort about what I feel I lack; unlike jealousy, it is not primarily about losing a valued relationship.', true, 137),
('EMO_138', 'EFAM_009', 'Tự hào', 'Proud', '🏅', '#E9C46A', 'Mình thấy trân trọng một nỗ lực, phẩm chất hoặc điều có ý nghĩa mà bản thân đã làm; cảm giác ấy cũng có thể hướng tới người mình gắn bó. Khác với đắc ý thường xoay quanh một lần làm đúng hay được như ý, tự hào nhấn vào điều mình coi là đáng ghi nhận.', 'I feel appreciative of a meaningful effort, quality, or achievement in myself, or in someone I identify with. Unlike being pleased with a particular success or being right, pride emphasizes what I regard as worthy of recognition.', true, 138),
('EMO_139', 'EFAM_010', 'Mệt mỏi', 'Tired / Fatigued', '😩', '#72879A', 'Mình cảm thấy năng lượng thể chất hoặc tinh thần đã giảm và những việc bình thường cũng cần nhiều sức hơn để thực hiện. Khác với kiệt sức là trạng thái cạn gần hết nguồn lực, mệt mỏi vẫn cho phép mình tiếp tục nhưng rõ ràng cần được nghỉ hoặc hồi lại.', 'My physical or mental energy feels reduced, making ordinary activities require more effort than usual. Unlike exhaustion, where resources feel almost depleted, fatigue still allows me to continue but signals a clear need for rest or recovery.', true, 139),
('EMO_140', 'EFAM_010', 'Kiệt sức', 'Exhausted', '🪫', '#667085', 'Mình cảm thấy sức lực thể chất hoặc tinh thần gần cạn, khiến việc tiếp tục những điều thường ngày cũng rất tốn sức. Đây là mức cạn kiệt đang trải nghiệm, không phải chỉ thiếu hứng thú, không đồng nghĩa với nhu cầu nghỉ ngơi và không tự xác định một chẩn đoán.', 'My physical or mental resources feel depleted enough that continuing ordinary activities takes considerable effort. This describes exhaustion, not merely low interest, a need for rest, or a diagnosis.', true, 140),
('EMO_141', 'EFAM_010', 'Mỏi mệt chuyện cũ', 'Weary of old troubles / Altschmerz', '🩹', '#78818F', 'Mình thấy mỏi mệt và chán vì tâm trí lại quay về những chuyện cũ mình đã nghĩ quá nhiều lần. Khác với ngán ngẩm một tình huống lặp lại ở bên ngoài, trọng tâm ở đây là sự hao mòn vì cứ phải sống lại cùng nỗi lo trong đầu.', 'I feel weary of returning mentally to old troubles I have thought about many times. Unlike being fed up with a repeated external situation, this centers on the fatigue of revisiting the same inner concerns.', true, 141),
('EMO_142', 'EFAM_010', 'Muốn nán lại trong chăn', 'Reluctant to leave bed', '🛌', '#7B879D', 'Mình thấy dễ chịu khi còn ở trong chăn và có lực kéo muốn nán lại, dù có thể không còn buồn ngủ. Đây là sự lưu luyến cảm giác nằm nghỉ, khác với kiệt sức là thiếu sức để tiếp tục và không phải kết luận về một tình trạng lâm sàng.', 'I feel comfortable under the covers and drawn to remain there even if I am no longer sleepy. This names reluctance to leave that comfort, unlike exhaustion as depleted capacity, and does not identify a clinical condition.', true, 142),
('EMO_143', 'EFAM_010', 'Chán', 'Bored', '🥱', '#6C757D', 'Mình thấy khó hứng thú hoặc gắn sự chú ý với điều đang làm, và thời gian có thể trôi chậm. Khác với ngán ngẩm có thêm bực bội vì chịu một chuyện lặp lại, chán không nhất thiết có sự phản đối hay giận dữ.', 'I find it difficult to feel engaged with what I am doing, and time may seem to pass slowly. Unlike being fed up, which adds irritation at repeated experiences, boredom does not necessarily involve anger or protest.', true, 143),
('EMO_144', 'EFAM_010', 'Meh – Hờ hững', 'Meh / Indifferent', '🫤', '#718096', 'Mình nhận biết điều đang xảy ra nhưng thấy ít quan tâm, ít bị thu hút hoặc tác động, như phản ứng chỉ là «cũng vậy thôi». Khác với tê lì là khó cảm nhận, hờ hững là ít quan tâm; khác với trung tính là vẫn hiện diện mà không rõ vui buồn.', 'I notice what is happening but feel little concern, attraction, or emotional investment, as though my response is ''meh''. Unlike numbness, this is low interest rather than reduced access to feeling; neutral presence need not involve indifference.', true, 144),
('EMO_145', 'EFAM_010', 'Mất động lực', 'Demotivated', '🧯', '#5C677D', 'Điều từng khiến mình muốn bắt đầu hoặc tiếp tục không còn tạo được lực kéo như trước. Mình có thể vẫn biết việc ấy quan trọng, nhưng không còn cảm thấy lý do, phần thưởng hoặc năng lượng đủ gần để hành động.', 'What once moved me to begin or continue no longer creates the same pull. I may still know that the task matters, but the reason, reward, or energy no longer feels close enough to support action.', true, 145),
('EMO_146', 'EFAM_010', 'Nản lòng', 'Discouraged', '💧', '#64748B', 'Sau thất bại, vật cản hoặc một thời gian cố gắng mà chưa thấy kết quả, lòng tin và năng lượng để tiếp tục đang giảm xuống. Mình chưa hẳn tin rằng không còn hy vọng, nhưng bắt đầu không chắc cố thêm có còn đáng hay có tạo ra khác biệt không.', 'After setbacks or prolonged effort without progress, my confidence and energy to continue are declining. I may not believe that all hope is gone, but I am beginning to question whether further effort is worthwhile or effective.', true, 146),
('EMO_147', 'EFAM_010', 'Vô vọng', 'Hopeless', '🌘', '#475569', 'Mình khó nhìn thấy một tương lai có thể tốt hơn hoặc một con đường thực sự dẫn ra khỏi tình hình hiện tại. Không chỉ thiếu sức để tiếp tục, mình còn khó tin rằng việc tiếp tục có thể tạo ra một khác biệt có ý nghĩa.', 'I struggle to imagine a better future or a viable way out of the current situation. I am not only low on energy; I also find it difficult to believe that continued effort could make a meaningful difference.', true, 147),
('EMO_148', 'EFAM_010', 'Trống rỗng', 'Empty', '🫙', '#6974A4', 'Bên trong mình có cảm giác thiếu một điều đáng lẽ phải hiện diện — cảm xúc, kết nối, ý nghĩa hoặc sinh khí — nhưng mình chưa chắc điều gì đang thiếu. Mình không hoàn toàn không cảm nhận được; mình cảm nhận khá rõ chính khoảng trống ấy.', 'I sense the absence of something that should be present—emotion, connection, meaning, or vitality—without necessarily knowing what is missing. I am not feeling nothing; I can feel the emptiness itself.', true, 148),
('EMO_149', 'EFAM_010', 'Tê lì', 'Numb', '🧊', '#495057', 'Mình thấy cảm xúc bị giảm âm lượng hoặc ở xa, khó chạm tới dù biết chuyện đang xảy ra có thể quan trọng. Khác với trung tính vẫn nhận biết rõ nhưng không nghiêng vui buồn, tê lì là khó tiếp cận cảm xúc; một lần check-in không nói lên nguyên nhân.', 'My emotions feel muted or distant, even when I know that what is happening may matter. Unlike a neutral state with intact awareness, numbness involves reduced access to feeling; a check-in does not establish its cause.', true, 149),
('EMO_150', 'EFAM_010', 'Lạc lõng', 'Alienated', '🚪', '#778DA9', 'Mình thấy lệch nhịp và xa cách với nơi hay nhóm mình đang hiện diện, như thể chưa tìm được chỗ của mình. Khác với cô đơn nhấn vào thiếu gần gũi, lạc lõng nhấn vào sự không hòa vào bối cảnh; đó là cảm nhận của mình, không khẳng định người khác loại mình ra.', 'I feel out of step with the place or group around me, as though I cannot find my place. Unlike loneliness about missing closeness, alienation emphasizes not fitting the context; it does not establish that others are excluding me.', true, 150),
('EMO_151', 'EFAM_010', 'Muốn khép mình lại', 'Urge to withdraw / Mauerbauertraurigkeit', '🧱', '#596275', 'Mình cảm thấy muốn khép lại và tạo khoảng cách với người khác, kể cả người thường khiến mình thấy gần gũi, mà chưa hiểu rõ vì sao. Khác với hờn dỗi thường gắn với một chuyện làm mình chạnh lòng, trạng thái này không nhất thiết có một bất mãn cụ thể.', 'I feel an urge to close myself off and distance myself even from people I usually feel close to, without knowing clearly why. Unlike sulking over a particular relational hurt, this need not center on a specific grievance.', true, 151)
